syntax:
void foo(int x);  // Overloaded function declaration
void foo(double y);  // Another overload, distinguished by parameter type
// Implementation notes: The compiler performs overload resolution at compile-time using rules from [over.match]. Name mangling ensures each overload has a unique linker symbol, e.g., _Z3foo i for foo(int) and _Z3foo d for foo(double) in Itanium ABI.

code_example:
#include <iostream>
void print(int value) {
    std::cout << "Integer: " << value << std::endl;
}
void print(double value) {
    std::cout << "Double: " << value << std::endl;
}
int main() {
    print(10);      // Calls print(int)
    print(3.14);    // Calls print(double)
    return 0;
}
